public sealed class LanState {public int ViewerSeat=-1;public string[] OwnSecrets;public string Session,ModeId,CardPoolId;public int Revision,FirstSeat,Active,Turn,Winner,CardsPlayed,AnimationSequence,AnimationRemainingMs;public LanPlayerView[] Players;public int TurnClockSequence,TurnClockRemainingMs=-1;public int LogStart;public string[] Log;public string VisualSession;public MatchVisualEvent[] VisualEvents;public int ArenaWins0,ArenaWins1,ArenaGameNumber,ArenaSeriesWinner=-2;}
public sealed class LanMessage {public string PlayerName;public string Kind,Fingerprint,Code,PoolId,ModeId,ArenaSession,Message,LogSession;public int LogAck,Protocol=LanProtocol.Version,ReplyId,ChoiceIndex,ArenaRevision;public bool Success,FullEffectsEnabled,PresentationOnly;public LanCommand Command;public LanState State;public ArenaDraftView ArenaDraft;public SealedView Sealed;public string SealedAction,SealedCard;public int SealedAmount;public int EffectsLevel=-1;public EffectLevel ReadEffects(){return EffectsLevel==-1?(FullEffectsEnabled?EffectLevel.High:EffectLevel.Off):EffectSettings.FromWire(EffectsLevel);}}
public static class LanProtocol {
 public const int Version=4;public const int Port=42671,MaxFrame=131072;
 public static bool PrivateAddress(IPAddress address){if(address.AddressFamily!=AddressFamily.InterNetwork)return false;var b=address.GetAddressBytes();return b[0]==127||b[0]==10||b[0]==192&&b[1]==168||b[0]==172&&b[1]>=16&&b[1]<=31||b[0]==169&&b[1]==254;}
 public static IPEndPoint Endpoint(string value){var parts=value.Trim().Split(':');IPAddress address;int port=Port;if(parts.Length>2||!IPAddress.TryParse(parts[0],out address)||!PrivateAddress(address)||parts.Length==2&&(!Int32.TryParse(parts[1],out port)||port<1024||port>65535))throw new InvalidOperationException("请输入局域网 IPv4 地址，例如 192.168.1.8:42671。");return new IPEndPoint(address,port);}
 public static string Addresses(int port){return String.Join(" / ",Dns.GetHostAddresses(Dns.GetHostName()).Where(a=>PrivateAddress(a)&&!IPAddress.IsLoopback(a)).Select(a=>a+":"+port));}
 public static string Fingerprint(CardCatalog catalog){using(var sha=SHA256.Create()){string data=JsonData.Serializer().Serialize(catalog.Cards.Values.OrderBy(c=>c.Id,StringComparer.Ordinal).ToArray())+JsonData.Serializer().Serialize(catalog.Pools);byte[] app=File.ReadAllBytes(typeof(LanProtocol).Assembly.Location);return Convert.ToBase64String(sha.ComputeHash(Encoding.UTF8.GetBytes(data)))+":"+Convert.ToBase64String(sha.ComputeHash(app));}}
 public static string CompatibilityError(string expected,string actual){
  if(String.IsNullOrEmpty(expected)||String.IsNullOrEmpty(actual))return "程序或牌库版本不同，请双方使用同一份完整包。";
  if(expected==actual)return null;var own=expected.Split(':');var peer=actual.Split(':');
  if(own.Length!=2||peer.Length!=2)return "程序或牌库版本不同，请双方使用同一份完整包。";
  if(own[0]!=peer[0])return "双方牌库数据版本不同，请双方使用同一份完整发布包；不是保存卡组的问题。";
  return "双方程序构建版本不同，相同版本号也可能是不同文件。请双方使用同一份客户端。";
 }
 public static void WriteFrame(Stream stream,string text){byte[] data=Encoding.UTF8.GetBytes(text);if(data.Length==0||data.Length>MaxFrame)throw new InvalidDataException("联机消息大小无效。");byte[] header=BitConverter.GetBytes(IPAddress.HostToNetworkOrder(data.Length));stream.Write(header,0,4);stream.Write(data,0,data.Length);}
 static void ReadExact(Stream stream,byte[] data){int offset=0;while(offset<data.Length){int n=stream.Read(data,offset,data.Length-offset);if(n==0)throw new EndOfStreamException("对方已离开。");offset+=n;}}
 public static string ReadFrame(Stream stream){var header=new byte[4];ReadExact(stream,header);int size=IPAddress.NetworkToHostOrder(BitConverter.ToInt32(header,0));if(size<=0||size>MaxFrame)throw new InvalidDataException("联机消息大小无效。");var data=new byte[size];ReadExact(stream,data);return new UTF8Encoding(false,true).GetString(data);}
 internal static T Copy<T>(T value){return JsonData.Serializer().Deserialize<T>(JsonData.Serializer().Serialize(value));}

 public static LanState View(MatchEngine game,int seat,string session,int revision,int logStart=0){if(seat<0||seat>1)throw new InvalidDataException("快照视角无效。");if(logStart<0||logStart>game.Log.Count)throw new InvalidDataException("记录游标无效。");var visualEvents=Copy(game.VisualEvents.Where(e=>(e.RecipientSeat<0||e.RecipientSeat==seat)&&((e.Kind!="secret-armed"&&e.Kind!="secret-stolen")||e.Seat==seat&&e.RecipientSeat==seat)).ToArray());var view=new LanState{CardPoolId=game.CardPoolId,ViewerSeat=seat,OwnSecrets=game.SecretCards(seat),Session=session,ModeId=game.Mode.Id,Revision=revision,FirstSeat=game.FirstSeat,Active=game.Active,Turn=game.Turn,Winner=game.Winner,CardsPlayed=game.CardsPlayed,AnimationSequence=game.AnimationSequence,AnimationRemainingMs=game.AnimationRemainingMs,Players=new LanPlayerView[2],TurnClockSequence=game.TurnClockSequence,TurnClockRemainingMs=game.TurnClockRemainingMs,LogStart=logStart,Log=game.Log.Skip(logStart).ToArray(),VisualSession=game.VisualSession,VisualEvents=visualEvents};for(int n=0;n<2;n++){var p=game.Players[n];var scalar=PublicPlayerState.From(p);view.Players[n]=new LanPlayerView{Public=scalar,Board=Copy(p.Board.ToArray()),Hand=n==seat?Copy(p.Hand.ToArray()):new HandCard[0],DeckPreview=n==seat&&p.Hand.Any(h=>game.Card(h.CardId).BaseId==HunterRules.TrackingCardId)?p.Deck.Take(3).ToArray():null,HandCount=p.Hand.Count,DeckCount=p.Deck.Count};}return view;}
 public static MatchEngine ReadView(CardCatalog catalog,LanState view,MatchEngine previous=null){if(view==null||view.ViewerSeat<0||view.ViewerSeat>1||view.OwnSecrets==null||view.Players==null||view.Players.Length!=2||view.Active<0||view.Active>1||view.FirstSeat<0||view.FirstSeat>1)throw new InvalidDataException("对局快照无效。");var game=new MatchEngine(catalog,GameModes.Get(view.ModeId??"classic"));game.CardPoolId=view.CardPoolId??"classic-2014";catalog.Pool(game.CardPoolId);game.FirstSeat=view.FirstSeat;game.Active=view.Active;game.Turn=view.Turn;game.Winner=view.Winner;game.CardsPlayed=view.CardsPlayed;if(previous!=null)game.ClockNowMs=previous.ClockNowMs;game.ReceiveTurnClock(view.TurnClockSequence,view.TurnClockRemainingMs);if(previous!=null&&previous.VisualSession==view.VisualSession&&previous.Turn==view.Turn&&previous.TurnClockSequence==view.TurnClockSequence)game.LimitTurnClock(previous.TurnClockRemainingMs);if(view.AnimationRemainingMs<0||view.AnimationRemainingMs>MatchEngine.EntranceAnimationMs||view.AnimationSequence<0)throw new InvalidDataException("动画等待无效。");game.ReceiveAnimationWait(view.AnimationSequence,view.AnimationRemainingMs);if(view.Log==null)throw new InvalidDataException("对局记录缺失。");if(view.LogStart<0||view.LogStart>0&&(previous==null||previous.Log.Count<view.LogStart||previous.VisualSession!=view.VisualSession))throw new InvalidDataException("对局记录增量缺失。");if(view.LogStart>0)game.Log.AddRange(previous.Log.Take(view.LogStart));game.Log.AddRange(view.Log);if(view.VisualSession==null||view.VisualEvents==null||view.VisualEvents.Length>128)throw new InvalidDataException("视觉事件无效。");game.VisualSession=view.VisualSession;if(view.VisualEvents.Any(e=>e==null||e.RecipientSeat< -1||e.RecipientSeat>1||e.RecipientSeat>=0&&e.RecipientSeat!=view.ViewerSeat||(e.Kind=="secret-armed"||e.Kind=="secret-stolen")&&(e.RecipientSeat!=view.ViewerSeat||e.Seat!=view.ViewerSeat)))throw new InvalidDataException("私有提示视角无效。");game.VisualEvents.AddRange(view.VisualEvents);for(int n=0;n<2;n++){var p=view.Players[n];if(p==null||p.Board==null||p.Board.Length>game.Mode.BoardSlots||p.Hand==null||p.HandCount>game.Mode.HandLimit||p.HandCount<0||p.DeckCount<0||p.DeckCount>60||p.Public==null||p.Public.HeroMaxHealth<0||p.Public.HeroFormId!=null&&HeroReplacementRules.Hero(p.Public.HeroFormId)==null||p.Public.HeroAbilityId!=null&&HeroReplacementRules.Ability(p.Public.HeroAbilityId)==null||p.Public.Shadowform<0||p.Public.Shadowform>2||p.Public.SecretCount<0||p.Public.SecretCount>5||p.DeckPreview!=null&&(p.DeckPreview.Length>3||p.DeckPreview.Length>p.DeckCount||p.DeckPreview.Any(id=>id==null||!catalog.Cards.ContainsKey(id))))throw new InvalidDataException("对局快照无效。");p.Public.DisplayName=PlayerNames.Normalize(p.Public.DisplayName,n);p.Public.Apply(game.Players[n]);game.Players[n].ReportedHandCount=p.HandCount;game.Players[n].Board.AddRange(p.Board);game.Players[n].Hand.AddRange(p.Hand);game.PrivateDeckPreview[n]=p.DeckPreview??new string[0];for(int i=0;i<p.DeckCount;i++)game.Players[n].Deck.Add("HIDDEN");}if(view.OwnSecrets.Length>game.Players[view.ViewerSeat].SecretCount||view.OwnSecrets.Distinct().Count()!=view.OwnSecrets.Length||view.OwnSecrets.Any(id=>id==null||!catalog.Cards.ContainsKey(id)||!MatchEngine.Has(catalog.Card(id),"SECRET")))throw new InvalidDataException("己方奥秘状态无效。");game.RestoreOwnSecrets(view.ViewerSeat,view.OwnSecrets);return game;}
}
public sealed class LanHostGame {
 public MatchEngine Game{get;private set;}public string Session{get;private set;}public int Revision;int acknowledgedLog;public void AcknowledgeLog(string session,int count){if(session!=Game.VisualSession)return;if(count<0)throw new InvalidDataException("对局记录确认无效。");acknowledgedLog=Math.Max(acknowledgedLog,Math.Min(count,Game.Log.Count));}readonly int[] lastEmoteRequest=new int[2];readonly EffectLevel[] presentation=new EffectLevel[2];readonly CardCatalog catalog;readonly DeckDocument[] arenaDecks;readonly string[] playerNames;DateTime nextArenaGameUtc=DateTime.MaxValue;public int ArenaWins0{get;private set;}public int ArenaWins1{get;private set;}public int ArenaGameNumber{get;private set;}public int ArenaSeriesWinner{get;private set;}public bool LastPollStartedArenaGame{get;private set;}public bool LastPollResolvedSpell{get;private set;}
 public void SetPresentation(int seat,bool enabled){SetPresentation(seat,enabled?EffectLevel.High:EffectLevel.Off);}
 public void SetPresentation(int seat,EffectLevel level){presentation[seat]=EffectSettings.FromWire((int)level);Game.SetAnimationEffects((EffectLevel)Math.Max((int)presentation[0],(int)presentation[1]));}
 public LanHostGame(CardCatalog catalog,DeckDocument host,DeckDocument guest,int seed,int? firstSeat=null,string hostName=null,string guestName=null,GameModeDefinition mode=null){this.catalog=catalog;playerNames=new[]{hostName,guestName};ArenaSeriesWinner=-2;Session=Guid.NewGuid().ToString("N");Game=new MatchEngine(catalog,host,guest,seed,startingSeat:firstSeat??new Random(seed).Next(2),firstName:hostName,secondName:guestName,mode:mode);Game.Log[0]=(Game.Mode.Id=="arena"?"竞技对局开始 · ":"局域网对局开始 · ")+Game.PlayerLabel(0)+" / "+Game.PlayerLabel(1);if(Game.Mode.Id=="arena"){arenaDecks=new[]{host.Copy(),guest.Copy()};ArenaGameNumber=1;}}
 public bool PollTimeout(){LastPollStartedArenaGame=false;LastPollResolvedSpell=false;if(Game.PollSpellImpact()){LastPollResolvedSpell=true;if(Game.Finished&&Game.Mode.Id=="arena")RecordArenaResult(null);Revision++;return true;}if(nextArenaGameUtc<DateTime.UtcNow&&ArenaSeriesWinner==-2){StartNextArenaGame();LastPollStartedArenaGame=true;Revision++;return true;}if(!Game.TryEndTimedTurn())return false;if(Game.Finished&&Game.Mode.Id=="arena")RecordArenaResult(null);Revision++;return true;}
 void RecordArenaResult(ActionResult result){if(ArenaSeriesWinner!=-2||!Game.Finished)return;if(Game.Winner>=0){if(Game.Winner==0)ArenaWins0++;else ArenaWins1++;}if(ArenaWins0>=2)ArenaSeriesWinner=0;else if(ArenaWins1>=2)ArenaSeriesWinner=1;else if(ArenaGameNumber>=3)ArenaSeriesWinner=ArenaWins0==ArenaWins1?-1:ArenaWins0>ArenaWins1?0:1;else nextArenaGameUtc=DateTime.UtcNow.AddMilliseconds(1800);string score=ArenaWins0+" - "+ArenaWins1;string ending=ArenaSeriesWinner==-2?" · 下一局即将开始":ArenaSeriesWinner==-1?" · 三局结束，系列赛平局":" · "+Game.PlayerLabel(ArenaSeriesWinner)+" 赢得竞技赛";if(result!=null)result.Message+=" · 竞技赛 "+score+ending;}
 void StartNextArenaGame(){if(arenaDecks==null||ArenaSeriesWinner!=-2||ArenaGameNumber>=3||!Game.Finished)throw new InvalidOperationException("当前不能开始下一场竞技对局。");ArenaGameNumber++;nextArenaGameUtc=DateTime.MaxValue;Game=new MatchEngine(catalog,arenaDecks[0],arenaDecks[1],Environment.TickCount,startingSeat:new Random().Next(2),firstName:playerNames[0],secondName:playerNames[1],mode:GameModes.Arena);Game.SetAnimationEffects((EffectLevel)Math.Max((int)presentation[0],(int)presentation[1]));Game.Log[0]="竞技赛第 "+ArenaGameNumber+" 局 · "+Game.PlayerLabel(0)+" / "+Game.PlayerLabel(1);acknowledgedLog=0;lastEmoteRequest[0]=lastEmoteRequest[1]=0;}
 public ActionResult Execute(int seat,LanCommand command){if(seat>=0&&seat<2&&command!=null&&command.Session==Session&&PollTimeout())return Fail(LastPollResolvedSpell?"法术已命中，请按最新状态操作。":LastPollStartedArenaGame?"竞技赛下一局已开始，请重新操作。":"倒计时结束，已自动换边。");if(seat<0||seat>1||command==null||command.Session!=Session||command.Revision!=Revision&&command.Kind!="emote")return Fail("状态已更新，请重新操作。");if(command.Target!=null&&(command.Target.Seat<0||command.Target.Seat>1||command.Target.UnitId<0)||command.Source<0||command.Position< -1||command.Position>7)return Fail("操作参数无效。");if(command.Kind=="emote"&&command.RequestId>0&&command.RequestId<=lastEmoteRequest[seat])return Fail("重复对话请求。");ActionResult result;if(command.Kind=="mulligan")result=Game.Mulligan(seat,command.SelectedHandIds);else if(command.Kind=="emote")result=Game.Emote(seat,command.Emote);else{if(seat!=Game.Active)return Fail("当前不是你的回合。");switch(command.Kind){case "play":result=Game.Play(seat,command.Source,command.Target,command.Position,command.Choice);break;case "attack":result=Game.Attack(seat,command.Source,command.Target);break;case "power":result=Game.HeroPower(seat,command.Target);break;case "end":result=Game.EndTurn();break;default:return Fail("未知操作。");}}if(result.Success){if(command.Kind=="emote"){if(command.RequestId>0)lastEmoteRequest[seat]=command.RequestId;}else{Revision++;if(Game.Mode.Id=="arena"&&Game.Finished)RecordArenaResult(result);}}return result;}
 static ActionResult Fail(string text){return new ActionResult{Message=text};}
 public LanMessage Snapshot(ActionResult result=null,int replyId=0,bool presentationOnly=false){var state=LanProtocol.View(Game,1,Session,Revision,acknowledgedLog);state.ArenaWins0=ArenaWins0;state.ArenaWins1=ArenaWins1;state.ArenaGameNumber=ArenaGameNumber;state.ArenaSeriesWinner=ArenaSeriesWinner;return new LanMessage{Kind="state",PresentationOnly=presentationOnly,State=state,ReplyId=replyId,Success=result==null||result.Success,Message=result==null?(Game.Mode.Id=="arena"?"竞技赛 · "+ArenaScoreLabel():"局域网对局已连接。"):result.Message};}
 public string ArenaScoreLabel(){return ArenaWins0+" - "+ArenaWins1+(ArenaSeriesWinner==-2?" · 第 "+ArenaGameNumber+" 局":ArenaSeriesWinner==-1?" · 系列赛平局":" · "+Game.PlayerLabel(ArenaSeriesWinner)+" 赢得竞技赛");}
}
// Background transport only. Game state is mutated on the WPF dispatcher.
public sealed class LanPeer : IDisposable {
 public event Action<LanMessage> Received;public event Action<string> Disconnected;public event Action Connected;
 readonly BlockingCollection<string> outgoing=new BlockingCollection<string>(64);volatile bool closed;TcpListener listener;TcpClient client;Timer heartbeat;
 public int ListeningPort{get;private set;}public bool IsConnected{get;private set;}
 public void Host(int port){listener=new TcpListener(IPAddress.Any,port);listener.Start(1);ListeningPort=((IPEndPoint)listener.LocalEndpoint).Port;Run(()=>{client=listener.AcceptTcpClient();listener.Stop();if(!LanProtocol.PrivateAddress(((IPEndPoint)client.Client.RemoteEndPoint).Address))throw new InvalidDataException("只接受局域网连接。");StartConnection();});}
 public void Join(IPEndPoint endpoint){Run(()=>{client=new TcpClient();if(closed){client.Close();return;}var pending=client.BeginConnect(endpoint.Address,endpoint.Port,null,null);using(pending.AsyncWaitHandle){if(!pending.AsyncWaitHandle.WaitOne(5000))throw new IOException("连接超时，请检查地址与房间状态。");client.EndConnect(pending);}StartConnection();});}
 void Run(Action action){new Thread(()=>{try{action();}catch(Exception ex){if(!closed){var notify=Disconnected;Dispose();if(notify!=null)notify(ex is SocketException?"连接失败或断开，请检查局域网与防火墙。":ex.Message);}}}){IsBackground=true}.Start();}
 void StartConnection(){if(closed){client.Close();return;}client.NoDelay=true;client.ReceiveTimeout=20000;client.SendTimeout=3000;IsConnected=true;var stream=client.GetStream();Run(()=>{foreach(string text in outgoing.GetConsumingEnumerable()){if(closed)break;LanProtocol.WriteFrame(stream,text);}});heartbeat=new Timer(s=>{if(!closed)Send(new LanMessage{Kind="ping"});},null,5000,5000);var ready=Connected;if(ready!=null)ready();while(!closed){var message=JsonData.Serializer().Deserialize<LanMessage>(LanProtocol.ReadFrame(stream));if(message==null)throw new InvalidDataException("联机消息无效。");if(message.Kind=="ping")continue;var received=Received;if(received!=null)received(message);}}
 public bool Send(LanMessage message){if(closed)return false;string text=JsonData.Serializer().Serialize(message);if(Encoding.UTF8.GetByteCount(text)>LanProtocol.MaxFrame)return false;try{return outgoing.TryAdd(text);}catch(InvalidOperationException){return false;}}
 public void Dispose(){if(closed)return;closed=true;IsConnected=false;if(heartbeat!=null)heartbeat.Dispose();if(listener!=null)listener.Stop();if(client!=null)client.Close();outgoing.CompleteAdding();}
}
